// Avsändare: hämtas från det Gmail-konto som faktiskt skickar, så att
// signaturen aldrig kan skilja sig från avsändaren. Välj samma credential i
// "Who is sending?" som i "Send email".
const SENDER_NAMES = {   // behövs bara när namnet inte följer av adressen
  'accounts@fcurban.com': 'Joep',   // delad brevlåda, signerar som Joep
  'joep@fcurban.com': 'Joep',
  'nicky@fcurban.com': 'Nicky',
  'brian@fcurban.com': 'Brian',
  'luuk@fcurban.com': 'Luuk',
  'stan@fcurban.com': 'Stan',
  'nero@fcurban.com': 'Nero',
};
const senderEmail = String($('Who is sending?').first().json.emailAddress ?? '').trim().toLowerCase();
const localPart = senderEmail.split('@')[0].replace(/[._\-+0-9].*$/, '');
const SENDER = SENDER_NAMES[senderEmail]
  || (localPart ? localPart.charAt(0).toUpperCase() + localPart.slice(1) : '');
if (!SENDER) {
  throw new Error(
    `Kunde inte avgöra avsändarnamnet från "${senderEmail}". Kontrollera credentialen ` +
    `på noden "Who is sending?", eller lägg till adressen i SENDER_NAMES.`
  );
}

// Avregistreringsrad, för GDPR-täckning vid kall B2B-utskick. Sätt till '' för att ta bort.
const OPT_OUT = 'Inte intresserad? Svara på det här mejlet så hör jag inte av mig igen.';

const row = $json;
// Ta bort en avslutande parentes så det inte står "Hej MOO Print Limited (UK),".
const business = (String(row['Business'] ?? '').replace(/\s*\([^)]*\)\s*$/, '').trim()
                  || String(row['Business'] ?? '').trim() || 'där');
const venue = String(row['Nearest FC Urban venue'] ?? '').trim();
const city  = String(row['City'] ?? '').trim() || 'er stad';
const walk  = Number(row['Walk (min)']);

// WhatsApp går bara fram till mobilnummer. Ungefär 90% av det här arket är
// fasta nummer, så de flesta raderna ger '' här och skickas förbi
// WhatsApp-grenen av IF-noden.
function mobileE164(raw) {
  const d = String(raw ?? '').replace(/[^\d+]/g, '');
  if (!d.startsWith('+')) return '';
  const n = d.slice(1);
  const isMobile =
       /^447\d{9}$/.test(n)        // UK
    || /^316\d{8}$/.test(n)        // NL
    || /^467\d{8}$/.test(n)        // SE
    || /^491[5-7]\d{7,9}$/.test(n) // DE
    || /^34[67]\d{8}$/.test(n)     // ES
    || /^324\d{8}$/.test(n);       // BE
  return isMobile ? n : '';
}
const waTo = mobileE164(row['Phone (international)']);

// Företagsnamn innehåller & och ibland citattecken - escapa innan de når HTML.
const esc = (t) => String(t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const link = (text, url) => url ? `<a href="${esc(url)}">${esc(text)}</a>` : esc(text);

// Påstå bara ett avstånd som kalkylarket faktiskt anger.
let proximity;
if (venue && Number.isFinite(walk) && walk > 0) {
  const min = walk === 1 ? 'minuts' : 'minuters';
  proximity = `Vi har planer tillgängliga vid ${esc(venue)}, ungefär ${walk} ${min} promenad från ert kontor.`;
} else if (venue) {
  proximity = `Vi har planer tillgängliga vid ${esc(venue)}, precis runt hörnet från ert kontor.`;
} else {
  proximity = `Vi har planer tillgängliga i ${esc(city)}.`;
}

const venueSlug = VENUE_SLUGS[venue];
const venueLink = venue ? link(venue, venueSlug ? VENUE_BASE + venueSlug : '') : esc(city);
const closing = `Läs gärna mer om ${link('FC Urban', FC_URBAN_URL)}`
              + ` och om vår anläggning ${venueLink}.`;

const subject = `Fotboll efter jobbet för teamet på ${business}`;

const paras = [
  `Hej ${esc(business)},`,

  `Jag heter ${SENDER} och jobbar på FC Urban. Vi arrangerar fotbollsmatcher i ${esc(city)} `
  + `där man bara ansluter och spelar. Vi arrangerar också matcher särskilt för företag.`,

  proximity,

  `Vi letar efter någon på ${esc(business)} som skulle tycka att det vore kul att hjälpa till `
  + `att dra igång ett återkommande fotbollstillfälle efter jobbet för kollegorna.`,

  `FC Urban ordnar planen, fyller på gruppen med spelare vid behov, och sköter organisationen. `
  + `Vi behöver främst någon internt som gillar fotboll och kan få med sig kollegorna.`,

  `Skulle du kunna sätta mig i kontakt med den som ansvarar för friskvård, HR eller `
  + `personalaktiviteter i ${esc(city)}? Eller någon du vet skulle vilja dra igång det här? `
  + `Tack på förhand!`,

  closing,

  `Hälsningar,<br>${SENDER}<br>FC Urban`,
];
if (OPT_OUT) paras.push(`<span style="color:#888;font-size:12px">${esc(OPT_OUT)}</span>`);

const html = paras.map((p) => `<p>${p}</p>`).join('\n');

return { json: { ...row, to: row._to, waTo, waName: business, waVenue: venue || city, subject, html } };

